function a(t){if(t==null||t==="")return null;if(t instanceof Date)return Number.isNaN(t.getTime())?null:t;if(typeof t=="number")return!Number.isFinite(t)||t<=0?null:new Date(t<1e12?t*1e3:t);const n=String(t).trim();if(/^\d+$/.test(n)){const r=Number(n);return new Date(r<1e12?r*1e3:r)}const e=new Date(n);return Number.isNaN(e.getTime())?null:e}function m(t){const n=a(t);return n?n.toLocaleString("zh-CN",{hour12:!1}):"—"}function l(t){const n=a(t);return n?n.toLocaleTimeString("zh-CN",{hour12:!1}):"—"}function h(t){const n=a(t);return n?`${n.getFullYear()}-${i(n.getMonth()+1)}-${i(n.getDate())}`:"—"}function d(t){return t==null||Number.isNaN(t)?"—":t.toLocaleString("zh-CN",{maximumFractionDigits:2})}function N(t){return t==null||Number.isNaN(t)?"—":t<1e3?`${Math.round(t)} ms`:`${(t/1e3).toFixed(2)} s`}function i(t){return t<10?`0${t}`:String(t)}function c(t){return`${t.getFullYear()}-${i(t.getMonth()+1)}-${i(t.getDate())}`}function $(t){const n=new Date(t.getFullYear(),t.getMonth(),1),e=new Date(t.getFullYear(),t.getMonth()+1,0);return{from:c(n),to:c(e),days:e.getDate()}}function D(t){return`${t.getFullYear()} 年 ${t.getMonth()+1} 月`}const g=["日","一","二","三","四","五","六"];function M(t,n){const e=new Date(t.getFullYear(),t.getMonth(),n);return g[e.getDay()]}function b(t,n){return!t||!n||n<=0?0:Math.max(0,Math.min(100,Math.round(t/n*100)))}function w(t,n=Date.now()){const e=a(t);if(!e)return"";const r=Math.floor((n-e.getTime())/1e3);if(r<45)return"刚刚";const u=Math.floor(r/60);if(u<60)return`${u} 分钟前`;const f=Math.floor(u/60);if(f<24)return`${f} 小时前`;const o=Math.floor(f/24);if(o<30)return`${o} 天前`;const s=Math.floor(o/30);return s<12?`${s} 个月前`:`${Math.floor(o/365)} 年前`}export{m as a,d as b,h as c,i as d,$ as e,l as f,c as g,N as h,D as m,b as p,w as r,a as t,M as w};
